const paths={mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M4 7l8 6 8-6"/>',business:'<path d="M3 21h18M5 21V8h14v13M8 8V3h8v5M9 12h1M14 12h1M9 16h1M14 16h1"/>',home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',wallet:'<path d="M20 7H5a2 2 0 0 1 0-4h13v4M4 7v12a2 2 0 0 0 2 2h14V7M20 12h-6v5h6"/><path d="M17 14.5h.01"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',debt:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/>',invest:'<path d="M3 18l6-6 4 4 8-12M15 4h6v6"/>',spark:'<path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4M18 4h4"/>',settings:'<path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',chevron:'<path d="M9 5l7 7-7 7"/>',left:'<path d="M15 5l-7 7 7 7"/>',down:'<path d="M5 9l7 7 7-7"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>',up:'<path d="M7 17L17 7M7 7h10v10"/>',in:'<path d="M17 7L7 17M7 7v10h10"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18"/>',leaf:'<path d="M12 21v-8M12 15C3 15 4 7 4 7s8-1 8 8M12 12c0-8 8-9 8-9s2 9-8 9"/>',food:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M20 3c-4 2-5 7-4 9h4M20 3v18"/>',car:'<path d="M4 10l2-6h12l2 6M3 10h18v8H3zM6 18v3M18 18v3M6 14h2M16 14h2"/>',house:'<path d="M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>',bag:'<rect x="4" y="7" width="16" height="14" rx="2"/><path d="M8 7V5a4 4 0 0 1 8 0v2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="M15 15l6 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',close:'<path d="M6 6l12 12M18 6L6 18"/>',download:'<path d="M12 3v12M7 10l5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 15V3M7 8l5-5 5 5M4 16v5h16v-5"/>',clip:'<path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',check:'<path d="M5 12l4 4L19 6"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 2v6h-6"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.wallet}</svg>`;
const navigation=[['dashboard','home','Visão geral'],['transactions','wallet','Lançamentos'],['goals','target','Meus objetivos'],['debts','debt','Minhas dívidas'],['investments','invest','Investimentos'],['assistant','spark','Assistente Alva'],['business','business','Meu negócio']];
const pageInfo={business:['Seu negócio em boas mãos.','MEI, microempresa ou trabalho por conta própria. Um espaço para crescer.'],dashboard:['Seu dinheiro em equilíbrio.','Um passo de cada vez. Cada escolha conta.'],transactions:['Tudo no seu controle.','Receitas e despesas organizadas, sem complicação.'],goals:['Seus sonhos têm um plano.','Pequenas conquistas de hoje. Grandes possibilidades amanhã.'],debts:['Mais perto de ficar em dia.','Organize seus compromissos e acompanhe cada pagamento.'],investments:['Cultive seu amanhã.','Acompanhe seus aportes e explore cenários para o futuro.'],assistant:['Vamos conversar sobre dinheiro?','Converse com a Alva ou anexe sua planilha para atualizar todo o seu painel automaticamente.'],settings:['Um espaço com a sua cara.','Seu perfil, suas preferências e suas conexões.']};
const DEMO_KEY='alva-demo-v1';let data;try{data=JSON.parse(localStorage.getItem(DEMO_KEY))||sampleData();}catch{data=sampleData();}
ensureBusiness(data,true);
let authVisible=true;
let view='dashboard',month=dateISO().slice(0,7),demo=true,revision=0,saving=false,chartMode='flow',hidden=false,chatBusy=false;
let messages=[{role:'assistant',content:'Oi! Eu sou a Alva 🌿 Vamos dar mais clareza ao seu dinheiro?\n\nPosso analisar seus gastos, registrar lançamentos ou dívidas por conversa (ex.: "Gastei 85 no mercado") e também ler sua planilha (.xlsx, .csv) ou extrato (.ofx) para atualizar todo o seu painel automaticamente!'}];
const $=s=>document.querySelector(s);const monthLabel=()=>new Date(`${month}-15T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}).replace(' de ',' ');
const firstName=()=>data.profile.name.split(' ')[0]||'você';const initials=()=>data.profile.name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'AL';
const authUI=createAuthUI({api,icon,isVisible:()=>authVisible,render:()=>{shell();postRender();},onAuthenticated:enterAccount,openDemo:()=>{authVisible=false;demo=true;try{data=JSON.parse(localStorage.getItem(DEMO_KEY))||sampleData();}catch{data=sampleData();}ensureBusiness(data,true);navigate('dashboard');}});
const businessUI=createBusinessUI({getData:()=>data,getMonth:()=>month,icon,modal,commit,toast,stat,panelHeader,render:()=>{shell();postRender();}});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function shell(){document.body.classList.remove('menu-open');document.body.classList.toggle('screen-auth',authVisible);if(authVisible){document.body.dataset.view='auth';$('#app').innerHTML=authUI.render();return;}authUI.stop();const title=pageInfo[view]?.[0]||'';$('#app').innerHTML=`<input type="file" id="file-importer" class="visually-hidden" accept=".csv,.tsv,.txt,.xlsx,.ofx,.json" multiple><div class="mobile-overlay" data-action="close-menu"></div><aside class="sidebar" id="app-sidebar" aria-label="Menu principal"><button class="icon-button sidebar-close" data-action="close-menu" aria-label="Fechar menu">${icon('close')}</button><a href="#" class="brand" data-nav="dashboard"><img src="./logo.svg" alt="">alva<span style="color:#99ae7c;font-size:29px">.</span></a><p class="brand-sub">SEU PRÓXIMO PASSO</p><div class="nav-label">SEU ESPAÇO</div><nav class="nav" aria-label="Navegação principal">${navigation.map(([id,ico,label])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='assistant'?'<span class="pill">IA</span>':''}</button>`).join('')}</nav><div class="nav-separator"></div><nav class="nav"><button data-nav="settings" class="${view==='settings'?'active':''}">${icon('settings')}Configurações</button><button data-action="help">${icon('help')}Precisa de ajuda?</button></nav><div class="sidebar-bottom"><div class="grow-note"><div class="sprout">${icon('leaf')}</div><h3>O futuro começa<br>com um pequeno passo.</h3><p>Estamos aqui para caminhar<br>com você, todos os dias.</p></div><button class="user-card" data-nav="settings"><span class="avatar">${e(initials())}</span><span><strong>${e(data.profile.name||'Meu perfil')}</strong><small>${demo?'Perfil de demonstração':'Minha conta pessoal'}</small></span>${icon('down')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button menu-button" data-action="menu" aria-label="Abrir menu" aria-controls="app-sidebar" aria-expanded="false">${icon('menu')}</button>${icon('home')}<span>Meu espaço</span><span>/</span><b>${navigation.find(x=>x[0]===view)?.[2]||'Configurações'}</b></div><div class="top-actions">${demo?`<button class="button top-signin" data-action="login">${icon('lock')}Criar minha conta</button>`:''}<span class="sync-label"><i class="live-dot"></i>${demo?'Salvo neste navegador':saving?'Salvando…':'Conectado ao Supabase'}</span><button class="icon-button" data-action="privacy" aria-label="${hidden?'Mostrar':'Ocultar'} valores">${icon('eye')}</button><button class="icon-button notification" data-action="notifications" aria-label="Ver lembretes">${icon('bell')}</button><button class="avatar" data-nav="settings" aria-label="Abrir meu perfil">${e(initials())}</button></div></header><main id="main" class="main" tabindex="-1">${demo?`<div class="demo-access"><span>${icon('leaf')}Você está na demonstração. Seus dados reais começam na sua conta.</span><button class="button secondary" data-action="login">Criar minha conta${icon('arrow')}</button></div>`:''}<section class="intro"><div><div class="eyebrow">${icon(view==='dashboard'?'sun':'leaf')} ${view==='dashboard'?`OLÁ, ${e(firstName().toUpperCase())}`:'SEU PRÓXIMO PASSO'}</div><h1>${title}</h1><p>${pageInfo[view]?.[1]||''}</p></div><div class="intro-actions">${view==='business'?`<button class="button secondary" data-business="export">${icon('download')}Exportar</button><button class="button" data-business="record">${icon('plus')}Nova movimentação</button>`:''}${view==='dashboard'||view==='transactions'?`<button class="button secondary" data-action="import-file">${icon('upload')}Importar planilha</button><button class="button secondary" data-action="export">${icon('download')}Exportar</button><button class="button" data-action="transaction">${icon('plus')}Novo lançamento</button>`:view==='goals'?`<button class="button secondary" data-action="import-file">${icon('upload')}Importar</button><button class="button" data-action="goal">${icon('plus')}Criar objetivo</button>`:view==='debts'?`<button class="button secondary" data-action="import-file">${icon('upload')}Importar</button><button class="button" data-action="debt">${icon('plus')}Adicionar dívida</button>`:view==='investments'?`<button class="button secondary" data-action="import-file">${icon('upload')}Importar</button><button class="button" data-action="investment">${icon('plus')}Registrar investimento</button>`:view==='assistant'?`<button class="button secondary" data-action="import-file">${icon('clip')}Anexar planilha ou documento</button>`:''}</div></section>${['dashboard','transactions','business'].includes(view)?`<div class="toolbar"><div class="period"><button data-action="prev-month" aria-label="Mês anterior">${icon('left')}</button><span>${e(monthLabel())}</span><button data-action="next-month" aria-label="Próximo mês">${icon('chevron')}</button></div><span class="demo-tag">${icon(demo?'leaf':'lock')}${demo?'Demonstração · dados de exemplo':'Sua conta · dados pessoais'}</span></div>`:''}<div id="page-content">${renderPage()}</div><footer class="footer"><span>${icon('lock')}${demo?'Demonstração local · dados neste navegador':'Seus dados pertencem a você'}</span><span>Feito para o seu dia a dia. Com clareza, sempre. 🌱</span></footer></main></div><nav class="mobile-bottom" aria-label="Atalhos">${[navigation[0],navigation[1],navigation[6],navigation[2],navigation[5]].map(([id,ic,label])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}${id==='dashboard'?'Início':id==='transactions'?'Lançamentos':id==='goals'?'Objetivos':id==='business'?'Negócio':'Alva'}</button>`).join('')}</nav>`;document.body.classList.toggle('screen-privacy',hidden);}
function stat(label,value,ico,foot,cls=''){const amount=money(value).replace('R$','').trim();return `<article class="stat"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value money ${cls}" data-counter-value="${value}" data-counter-key="${e(label)}"><span class="currency" aria-hidden="true">R$</span><span class="counter-number" aria-hidden="true">${amount}</span><span class="visually-hidden">${money(value)}</span></div><div class="stat-foot">${foot}</div></article>`;}
function panelHeader(title,subtitle,action=''){return `<div class="panel-header"><div><h2>${title}</h2>${subtitle?`<p class="panel-subtitle">${subtitle}</p>`:''}</div>${action}</div>`;}
function renderPage(){if(view==='business')return businessUI.render();return ({dashboard:dashboard,transactions:transactions,goals:goals,debts:debts,investments:investments,assistant:assistant,settings:settings}[view]||dashboard)();}
function chart(){const days=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();const length=month===dateISO().slice(0,7)?new Date().getDate():days;const rows=data.transactions.filter(t=>t.date.startsWith(month));const income=[],expense=[],balance=[];let i=0,x=0;const before=data.profile.opening_balance+data.transactions.filter(t=>t.date<`${month}-01`).reduce((s,t)=>s+(t.type==='income'?t.amount:-t.amount),0);for(let d=1;d<=length;d++){rows.filter(t=>Number(t.date.slice(8))===d).forEach(t=>{if(t.type==='income')i+=t.amount;else x+=t.amount;});income.push(i);expense.push(x);balance.push(before+i-x);}const a=chartMode==='flow'?income:balance,b=chartMode==='flow'?expense:[];const max=Math.max(10000,...a,...b),min=Math.min(0,...a,...b),range=max-min||1;const coord=(v,idx)=>`${44+idx/Math.max(1,days-1)*492},${150-(v-min)/range*130}`;const line=values=>values.map((v,j)=>`${j?'L':'M'}${coord(v,j)}`).join(' ');const p=line(a),last=a.length?coord(a.at(-1),a.length-1):'44,150';return `<svg class="line-chart" viewBox="0 0 555 187" role="img" aria-label="${chartMode==='flow'?'Receitas e despesas acumuladas':'Saldo acumulado'} no mês"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a7c18b" stop-opacity=".2"/><stop offset="100%" stop-color="#a7c18b" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(n=>{const y=20+n*43.33;return `<line x1="44" x2="540" y1="${y}" y2="${y}" stroke="#edf0e8" stroke-dasharray="3 4"/><text x="0" y="${y+3}">${((max-n*range/3)/100000).toLocaleString('pt-BR',{maximumFractionDigits:1})}k</text>`;}).join('')}<path d="${p} L ${last.split(',')[0]},150 L44,150Z" fill="url(#chart-fill)"/>${b.length?`<path d="${line(b)}" fill="none" stroke="#c3ceba" stroke-width="2" stroke-linejoin="round"/>`:''}<path d="${p}" fill="none" stroke="#759962" stroke-width="2.5" stroke-linejoin="round"/><circle cx="${last.split(',')[0]}" cy="${last.split(',')[1]}" r="4" fill="#71945d" stroke="white" stroke-width="2"/>${[1,5,10,15,20,25,days].map(d=>`<text x="${44+(d-1)/(days-1)*492}" y="176" text-anchor="middle">${String(d).padStart(2,'0')}</text>`).join('')}</svg>`;}
function dashboard(){const t=totals(data,month),budget=data.profile.monthly_budget;return `<section class="stats" aria-label="Resumo financeiro">${stat('Saldo disponível',t.balance,'wallet',`${icon('lock')}Saldo de todos os registros`)}${stat('Entradas do mês',t.income,'in',`${icon('in')}Receitas registradas`)}${stat('Saídas do mês',t.expense,'up',`${icon('up')}Despesas registradas`)}${stat('Guardado em objetivos',t.saved,'target',`${icon('leaf')}${data.goals.length} objetivos no seu caminho`)}</section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Seu dinheiro em movimento</h2><p class="panel-subtitle">Clareza para acompanhar suas escolhas</p></div><div class="chart-tabs"><button data-chart="flow" class="${chartMode==='flow'?'active':''}">Fluxo</button><button data-chart="balance" class="${chartMode==='balance'?'active':''}">Saldo</button></div></div><div class="chart-meta"><span><i class="legend-dot"></i>${chartMode==='flow'?'Entradas':'Saldo'}</span>${chartMode==='flow'?'<span><i class="legend-dot gray"></i>Saídas</span>':''}<span style="margin-left:auto">Acumulado do mês</span></div>${chart()}<div class="chart-bottom"><span>Dos seus registros, sem estimativas.</span><b>${t.income>=t.expense?'Entradas acima das saídas':'Revise seu orçamento'} ${icon('up')}</b></div></section><aside class="agent-card"><div class="agent-label"><span class="agent-mark">${icon('spark')}</span>Um olhar da Alva <small>IA ATIVA</small></div><h2>Pequenos passos.<br><em>Grandes possibilidades.</em></h2><p>${t.income>t.expense?`Você tem ${money(t.income-t.expense)} entre entradas e saídas do mês. Vamos planejar o próximo passo ou importar sua planilha?`:'Vamos olhar seus gastos, conversar ou importar sua planilha financeira?'}</p><button class="button light" data-nav="assistant">Conversar com a Alva${icon('arrow')}</button><div class="agent-foot">Assistente ativa · Aceita planilhas e extratos</div></aside><section class="panel">${panelHeader('Últimos lançamentos','Seu dia a dia, organizado',`<button class="text-button" data-nav="transactions">Ver todos${icon('chevron')}</button>`)}${transactionTable([...t.list].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4))}</section><section class="panel goals-panel">${panelHeader('Sonhos em construção','Cada pouquinho faz diferença',`<button class="text-button" data-nav="goals">${icon('chevron')}<span class="visually-hidden">Ver objetivos</span></button>`)}<div class="goals-mini">${data.goals.slice(0,2).map(goalMini).join('')||'<div class="empty">Qual é o seu próximo sonho?</div>'}</div><button class="button ghost" data-action="goal">${icon('plus')}Criar um novo objetivo</button></section></div><div class="bottom-grid"><section class="panel">${panelHeader('Para onde vai seu dinheiro','Saídas por categoria neste mês',`<span class="insight-tag">${budget?Math.round(t.expense/budget*100)+'% do orçamento':'Defina seu orçamento'}</span>`)}${budgetChart()}</section><section class="panel">${panelHeader('No seu radar','Compromissos que merecem atenção',`<button class="text-button" data-nav="debts">Ver dívidas${icon('chevron')}</button>`)}${data.debts.filter(d=>d.balance>0).slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,2).map(d=>`<div class="next-bill"><div class="date-tile"><small>${new Date(d.due+'T12:00:00').toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase()}</small>${d.due.slice(8)}</div><div class="bill-info">${e(d.name)}<p>Vencimento informado · saldo em aberto</p></div><span class="amount money">${money(d.balance)}</span></div>`).join('')||'<div class="empty">Nenhuma dívida em aberto. 🌱</div>'}</section></div>`;}
function categoryIcon(t){const ic=t.type==='income'?'wallet':t.category==='Alimentação'?'food':t.category==='Transporte'?'car':t.category==='Moradia'?'house':'bag';const cls=t.type==='income'?'receita':t.category==='Alimentação'?'alimentacao':t.category==='Transporte'?'transporte':t.category==='Moradia'?'moradia':'';return `<span class="category-icon ${cls}">${icon(ic)}</span>`;}
function transactionTable(list,full=false){return `<table class="transaction-table ${full?'full-table':''}"><thead><tr><th>Descrição</th><th class="category-column">Categoria</th><th>Data</th><th>Valor</th></tr></thead><tbody>${list.map(t=>`<tr><td><div class="transaction-name">${categoryIcon(t)}<div><strong>${e(t.name)}</strong><small>${t.type==='income'?'Entrada':'Saída'}${t.linked?' · vinculado':''}</small></div></div></td><td class="category-column"><span class="tag">${e(t.category)}</span></td><td class="muted">${new Date(t.date+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','')}</td><td><div class="row-actions"><span class="amount money ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'} ${money(t.amount)}</span>${full&&!t.linked?`<button class="delete-button" data-delete="${e(t.id)}" aria-label="Excluir ${e(t.name)}">${icon('trash')}</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">Nenhum lançamento neste período.<br>Comece registrando uma receita ou despesa.</div></td></tr>'}</tbody></table>`;}
function goalMini(g){const p=Math.min(100,Math.round(g.saved/g.target*100));return `<div><div class="goal-top"><span class="goal-emoji">${e(g.emoji)}</span><div><h3>${e(g.name)}</h3><p>${p===100?'Objetivo alcançado!':'Seu futuro agradece'}</p></div><span class="percentage">${p}%</span></div><div class="progress"><span style="width:${p}%"></span></div><div class="goal-values"><b class="money">${money(g.saved)}</b><span class="money">de ${money(g.target)}</span></div></div>`;}
function budgetChart(){const rows=budgetBreakdown(data,month);const colors=['#6b895b','#a6bb8e','#d1dbc1','#e1e7d5'];const total=rows.reduce((s,r)=>s+r[1],0);let acc=0;const gradients=rows.map((r,i)=>{const start=acc;acc+=r[1]/total*100;return `${colors[Math.min(i,3)]} ${start}% ${acc}%`;}).join(',');return `<div class="budget-content"><div class="donut" style="background:${total?'conic-gradient('+gradients+')':'#edf0e7'}"><div class="donut-center money">${money(total).replace(/,00$/,'')}<small>em saídas</small></div></div><div class="budget-list">${rows.slice(0,4).map(([cat,v],i)=>`<div class="budget-row"><span><i style="background:${colors[i]}"></i>${e(cat)}</span><b class="money">${money(v)}</b></div>`).join('')||'<p class="muted">Sem despesas neste mês.</p>'}</div></div>`;}
function transactions(){return `<section class="panel"><div class="filter-bar"><label class="search">${icon('search')}<input class="input" id="search" placeholder="Buscar um lançamento…" aria-label="Buscar lançamento"></label><select id="type-filter" aria-label="Filtrar por tipo"><option value="all">Todas as movimentações</option><option value="expense">Saídas</option><option value="income">Entradas</option></select><select id="category-filter" aria-label="Filtrar por categoria"><option value="all">Todas as categorias</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select></div><div id="transaction-results">${transactionTable(totals(data,month).list.slice().sort((a,b)=>b.date.localeCompare(a.date)),true)}</div></section>`;}
function goals(){return `<div class="tip">${icon('leaf')}<div><strong>Cada objetivo começa com um passo.</strong><br>Ao guardar dinheiro, a Alva atualiza sua meta e registra a saída no seu saldo.</div></div><div class="content-grid">${data.goals.map(g=>`<section class="panel large-goal"><span class="goal-emoji">${e(g.emoji)}</span><h2>${e(g.name)}</h2><p class="panel-subtitle">${g.deadline?'Até '+new Date(g.deadline+'T12:00:00').toLocaleDateString('pt-BR'):'No seu tempo'} · ${Math.min(100,Math.round(g.saved/g.target*100))}% conquistado</p><div class="progress"><span style="width:${Math.min(100,g.saved/g.target*100)}%"></span></div><div class="goal-values"><b class="money">${money(g.saved)}</b><span class="money">de ${money(g.target)}</span></div><button class="button secondary" data-contribute="${e(g.id)}" ${g.saved>=g.target?'disabled':''}>${icon(g.saved>=g.target?'check':'plus')}${g.saved>=g.target?'Objetivo alcançado':'Guardar para este objetivo'}</button></section>`).join('')||'<section class="panel empty">Crie seu primeiro objetivo.<br>Uma viagem, uma reserva ou um novo começo.</section>'}</div>`;}
function debts(){const t=totals(data,month);return `<div class="tip">${icon('debt')}<div><strong class="money">${money(t.debt)} em dívidas registradas.</strong><br>Acompanhe as parcelas, o vencimento e os pagamentos de cada compromisso.</div></div><div class="content-grid">${[...data.debts].sort((a,b)=>(b.balance>0)-(a.balance>0)||a.due.localeCompare(b.due)).map(d=>{const count=Math.max(1,Number(d.installments)||1);return `<section class="panel debt-card">${panelHeader(e(d.name),'Saldo em aberto',`<div class="row-actions"><span class="tag">${d.balance?'Em andamento':'Quitada'}</span><button class="delete-button" data-delete-debt="${e(d.id)}" aria-label="Excluir ${e(d.name)}" title="Excluir dívida">${icon('trash')}</button></div>`)}<div class="debt-total money">${money(d.balance)}</div><div class="progress"><span style="width:${Math.max(0,(1-d.balance/d.total)*100)}%"></span></div><div class="detail"><span>Já pago</span><b class="money">${money(d.total-d.balance)}</b></div><div class="detail"><span>Parcelas</span><b>${count}x de ${money(Math.round(d.total/count))}</b></div><div class="detail"><span>Vencimento</span><b>${new Date(d.due+'T12:00:00').toLocaleDateString('pt-BR')}</b></div><button class="button secondary" data-pay="${e(d.id)}" ${!d.balance?'disabled':''}>${icon(d.balance?'check':'leaf')}${d.balance?'Registrar pagamento':'Dívida quitada'}</button></section>`;}).join('')||'<section class="panel empty">Nenhuma dívida cadastrada.<br>Adicione um compromisso para acompanhar os pagamentos.</section>'}</div><p class="form-note">O saldo é atualizado pelos pagamentos registrados.</p>`;}
function investments(){const t=totals(data,month);return `<div class="investment-grid"><section class="panel">${panelHeader('Seu patrimônio investido','Valores informados por você')}<div class="debt-total money">${money(t.invested)}</div>${data.investments.map(i=>`<div class="next-bill"><span class="category-icon receita">${icon('invest')}</span><div class="bill-info">${e(i.name)}<p>${e(i.kind)}</p></div><span class="amount money">${money(i.amount)}</span></div>`).join('')||'<p class="empty">Registre seus investimentos para acompanhar o patrimônio.</p>'}<div class="notice">Os valores não são atualizados por cotações. Registrar um investimento adiciona uma saída no seu saldo; o saldo inicial deve considerar valores anteriores.</div></section><section class="panel">${panelHeader('E se você começasse hoje?','Simule um cenário com os seus próprios números')}<form method="post" id="simulator" class="form-grid"><label class="field">Valor inicial (R$)<input class="input" name="initial" type="number" min="0" max="100000000" value="1000" step="0.01" required></label><label class="field">Aporte mensal (R$)<input class="input" name="monthly" type="number" min="0" max="1000000" value="300" step="0.01" required></label><label class="field">Taxa hipotética (% ao ano)<input class="input" name="rate" type="number" min="0" max="100" value="6" step="0.1" required></label><label class="field">Prazo (anos)<input class="input" name="years" type="number" min="1" max="50" value="5" step="1" required></label></form><div id="simulation-output"></div><p class="form-note">Cenário ilustrativo, com aportes ao fim de cada mês. Valores brutos, sem impostos, taxas e inflação. A taxa é uma hipótese, sem garantia de retorno.</p></section></div>`;}
function assistant(){return `<div class="chat-layout"><section class="panel chat-panel"><div class="chat-header"><span class="agent-mark">${icon('spark')}</span><div><h2>Sua assistente Alva</h2><p>Assistente ativa · Converse ou anexe uma planilha para atualizar seu painel</p></div><span class="tag" style="margin-left:auto">IA Ativa</span></div><div class="chat-messages" id="chat-messages" aria-live="polite">${messages.map(m=>`<div class="message ${m.role}">${e(m.content)}</div>`).join('')}${chatBusy?'<div class="message assistant typing" role="status"><span class="visually-hidden">Alva está preparando a resposta.</span><span class="page-busy" aria-hidden="true"><i></i><i></i><i></i></span></div>':''}</div><form method="post" id="chat-form" class="chat-input"><button class="button secondary chat-attach" type="button" data-action="import-file" title="Anexar planilha ou documento (.xlsx, .csv, .ofx, .txt)" aria-label="Anexar planilha ou documento">${icon('clip')}<span class="chat-send-label">Anexar</span></button><input class="input" name="message" placeholder="Pergunte algo, diga 'Gastei 50 no mercado' ou anexe sua planilha…" maxlength="2000" aria-label="Mensagem para a Alva" required><button class="button" type="submit" ${chatBusy?'disabled':''} aria-label="Enviar mensagem">${icon('arrow')}<span class="chat-send-label">Enviar</span></button></form></section><aside class="chat-context"><section class="panel">${panelHeader('Migrar planilha','Atualize o painel automaticamente')}<p class="muted" style="font-size:11px;line-height:1.7;margin-bottom:14px">Tem uma planilha pronta (.xlsx, .csv) ou extrato (.ofx)? Anexe o documento e a Alva preenche seus lançamentos, dívidas e metas na hora.</p><button class="button" style="width:100%" type="button" data-action="import-file">${icon('upload')}Anexar documento</button></section><section class="panel" style="margin-top:16px">${panelHeader('Um bom começo','Escolha um assunto para conversar')}<div class="chat-suggestions">${['Quanto gastei este mês?','Como posso juntar para minha meta?','Como estão minhas dívidas?','Quero simular um investimento'].map(q=>`<button class="suggestion" data-question="${e(q)}">${e(q)} ${icon('arrow')}</button>`).join('')}</div></section></aside></div>`;}
function settings(){return `<div class="settings-layout"><section class="panel">${panelHeader('Meu perfil','O planejamento começa por você')}<form method="post" id="profile-form"><div class="form-grid"><label class="field full">Seu nome<input class="input" name="name" value="${e(data.profile.name)}" maxlength="70" required></label><label class="field">Orçamento mensal (R$)<input class="input" type="number" min="0" max="100000000" step="0.01" name="budget" value="${numeric(data.profile.monthly_budget)}" required></label><label class="field">Saldo inicial (R$)<input class="input" type="number" min="-100000000" max="100000000" step="0.01" name="opening" value="${numeric(data.profile.opening_balance)}" required></label></div><p>Saldo inicial é o valor disponível antes dos lançamentos cadastrados. O saldo atual soma receitas e subtrai despesas desse valor.</p><button class="button" type="submit">${icon('check')}Salvar perfil</button></form><div class="connection-state">${icon('lock')}${demo?'Perfil de demonstração':'Conta pessoal autenticada'}</div></section><section class="panel">${panelHeader('Minha conta',demo?'Seu espaço pessoal começa pelo e-mail':'Seu acesso à Alva')}${demo?`<p>Crie sua conta com e-mail e uma senha pessoal. Os lançamentos de exemplo ficam na demonstração; sua conta começa com os seus números.</p><button class="button" data-action="login">${icon('mail')}Criar minha conta</button>`:`<p>${icon('mail')} ${e(api.session?.user?.email||'E-mail cadastrado')}</p><p>Você entra com e-mail e senha. Os dados financeiros e do negócio ficam vinculados à sua conta.</p><button class="button ghost" data-action="logout">Sair da minha conta</button>`}</section><section class="panel">${panelHeader('Seus dados, com você','Importe ou exporte quando quiser')}<p>Traga sua planilha (.xlsx, .csv) ou extrato (.ofx) para atualizar o painel automaticamente, ou baixe seus lançamentos em CSV.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button" type="button" data-action="import-file">${icon('upload')}Importar planilha</button><button class="button secondary" type="button" data-action="export">${icon('download')}Exportar lançamentos</button></div></section><section class="panel">${panelHeader('Sobre a Alva','Seu dinheiro, com clareza')}<p>Um espaço para cuidar do seu dia a dia, acompanhar sonhos e organizar também o seu negócio.</p><p>${demo?'Demonstração com armazenamento neste navegador.':'Conta pessoal com dados sincronizados.'}</p></section></div>`;}
function modal(title,body,formId='record-form',submit='Salvar'){const opener=document.activeElement;const m=$('#modal');m.innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Fechar">${icon('close')}</button></div>${formId?`<form method="post" id="${formId}">${body}<p class="form-error" id="modal-error" role="alert"></p><div class="modal-actions"><button class="button secondary" type="button" data-action="close-modal">Cancelar</button><button class="button" type="submit">${submit}</button></div></form>`:body}`;if(!m.open)m.showModal();animateModal(m,opener);}
const inputField=(label,name,type='text',value='',attrs='')=>`<label class="field">${label}<input class="input" name="${name}" type="${type}" value="${e(value)}" ${attrs} required></label>`;
function recordModal(kind,id){let body='';const common=`<input type="hidden" name="kind" value="${kind}"><input type="hidden" name="id" value="${e(id||'')}">`;
 if(kind==='transaction'){const t=data.transactions.find(t=>t.id===id);body=`<div class="form-grid"><label class="field full">Descrição<input class="input" name="name" value="${e(t?.name||'')}" placeholder="Ex.: mercado da semana" maxlength="100" required></label>${inputField('Valor (R$)','amount','number',t?numeric(t.amount):'','min="0.01" max="100000000" step="0.01"')}<label class="field">Tipo<select name="type"><option value="expense" ${t?.type==='expense'?'selected':''}>Saída</option><option value="income" ${t?.type==='income'?'selected':''}>Entrada</option></select></label><label class="field">Categoria<select name="category">${categories.map(c=>`<option ${t?.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${inputField('Data','date','date',t?.date||dateISO(),`max="${dateISO()}"`)}</div>`;}
 if(kind==='goal')body=`<div class="form-grid"><label class="field full">O que você quer conquistar?<input class="input" name="name" maxlength="80" placeholder="Ex.: minha reserva de emergência" required></label>${inputField('Quanto quer juntar? (R$)','amount','number','','min="0.01" max="100000000" step="0.01"')}<label class="field">Símbolo<select name="emoji"><option>🌱</option><option>✈️</option><option>🏡</option><option>🎓</option><option>🚗</option><option>💻</option><option>✨</option></select></label><label class="field full">Prazo (opcional)<input class="input" name="deadline" type="date" min="${dateISO()}"></label></div>`;
 if(kind==='debt')body=`<div class="form-grid"><label class="field full">Nome da dívida<input class="input" name="name" maxlength="80" placeholder="Ex.: cartão de crédito" required></label>${inputField('Saldo em aberto (R$)','amount','number','','min="0.01" max="100000000" step="0.01"')}${inputField('Quantidade de parcelas','installments','number','1','min="1" max="360" step="1"')}${inputField('Próximo vencimento','due','date',dateISO())}</div><p class="form-note">Informe o saldo atual e o número de parcelas. A Alva registra os pagamentos conforme você avança.</p>`;
 if(kind==='investment')body=`<div class="form-grid"><label class="field full">Nome do investimento<input class="input" name="name" maxlength="80" placeholder="Ex.: aporte para o futuro" required></label>${inputField('Valor aplicado (R$)','amount','number','','min="0.01" max="100000000" step="0.01"')}<label class="field">Categoria<select name="category"><option>Renda fixa</option><option>Fundos</option><option>Ações</option><option>Outros</option></select></label></div><p class="form-note">Este registro também cria uma saída na categoria Investimentos, com a data de hoje.</p>`;
 if(kind==='contribute'||kind==='pay'){const item=(kind==='pay'?data.debts:data.goals).find(x=>x.id===id);const remaining=kind==='pay'?item.balance:Math.max(0,item.target-item.saved);body=`<p class="muted" style="margin-bottom:20px;font-size:12px">${e(item.name)} · ${kind==='pay'?'Em aberto':'Falta juntar'}: <b class="money">${money(remaining)}</b></p>${inputField(kind==='pay'?'Valor pago (R$)':'Valor para guardar (R$)','amount','number','',`min="0.01" max="${numeric(remaining)}" step="0.01"`)}<p class="form-note">O valor será registrado como saída no seu saldo. A ${kind==='pay'?'dívida':'meta'} será atualizada na mesma operação.</p>`;}
 modal({transaction:id?'Editar lançamento':'Novo lançamento',goal:'Um novo objetivo',debt:'Adicionar dívida',investment:'Registrar investimento',contribute:'Mais perto do seu sonho',pay:'Registrar pagamento'}[kind],common+body,'record-form',kind==='contribute'?'Guardar agora':kind==='pay'?'Registrar pagamento':'Salvar');}
async function commit(change,success='Salvo com sucesso.'){if(saving)throw new Error('Aguarde a operação atual terminar.');saving=true;const next=structuredClone(data);try{change(next);if(demo)localStorage.setItem(DEMO_KEY,JSON.stringify(next));else revision=await api.saveAccount(next,revision);data=next;saving=false;$('#modal').close();shell();postRender();toast(success);}finally{saving=false;}}
function formError(err,form){let msg=err.message||'Não foi possível salvar. Tente novamente.';if(/revision_conflict/.test(msg))msg='Há alterações feitas em outra aba ou dispositivo. Recarregue a página para atualizar os dados antes de salvar.';if(/Invalid login credentials/.test(msg))msg='E-mail ou senha incorretos. Confira seus dados.';const target=form?.querySelector('.form-error')||$('#modal-error');if(target)target.textContent=msg;else toast(msg);}
async function submitRecord(form){const f=Object.fromEntries(new FormData(form)),amount=cents(f.amount);await commit(next=>{const id=crypto.randomUUID();if(f.kind==='transaction'){if(!f.name.trim())throw new Error('Informe uma descrição.');const t={id:f.id||id,name:f.name.trim(),amount,type:f.type,category:f.category,date:f.date};if(f.id){const idx=next.transactions.findIndex(t=>t.id===f.id&&!t.linked);if(idx<0)throw new Error('Lançamento não encontrado.');next.transactions[idx]=t;}else next.transactions.push(t);}if(f.kind==='goal')next.goals.push({id,name:f.name.trim(),target:amount,saved:0,emoji:f.emoji,deadline:f.deadline});if(f.kind==='debt')next.debts.push({id,name:f.name.trim(),total:amount,balance:amount,installments:Math.max(1,Math.min(360,Math.round(Number(f.installments)||1))),due:f.due});if(f.kind==='investment'){next.investments.push({id,name:f.name.trim(),amount,kind:f.category});next.transactions.push({id:crypto.randomUUID(),name:f.name.trim(),category:'Investimentos',type:'expense',amount,date:dateISO(),linked:id});}if(f.kind==='contribute'||f.kind==='pay'){const pay=f.kind==='pay',item=(pay?next.debts:next.goals).find(x=>x.id===f.id);if(!item)throw new Error('Registro não encontrado.');if(amount>(pay?item.balance:item.target-item.saved))throw new Error('O valor ultrapassa o saldo restante.');if(pay)item.balance-=amount;else item.saved+=amount;next.transactions.push({id:crypto.randomUUID(),name:`${pay?'Pagamento':'Objetivo'}: ${item.name}`,category:pay?'Dívidas':'Metas',amount,type:'expense',date:dateISO(),linked:item.id});}},f.kind==='contribute'?'Mais um passo para o seu objetivo! 🌱':f.kind==='pay'?'Pagamento registrado e dívida atualizada.':'Registro salvo com sucesso.');}
function filterTransactions(){const q=($('#search')?.value||'').toLowerCase(),type=$('#type-filter')?.value,category=$('#category-filter')?.value;const list=totals(data,month).list.filter(t=>t.name.toLowerCase().includes(q)&&(type==='all'||t.type===type)&&(category==='all'||t.category===category)).sort((a,b)=>b.date.localeCompare(a.date));$('#transaction-results').innerHTML=transactionTable(list,true);attachEditButtons();}
function attachEditButtons(){if(view!=='transactions')return;$('#transaction-results')?.querySelectorAll('tbody tr').forEach(row=>{const del=row.querySelector('[data-delete]');if(del){const strong=row.querySelector('.transaction-name strong');strong.setAttribute('role','button');strong.tabIndex=0;strong.style.cursor='pointer';strong.title='Editar lançamento';strong.dataset.edit=del.dataset.delete;}});}
function simulate(){const form=$('#simulator');if(!form)return;const f=Object.fromEntries(new FormData(form));if(!form.checkValidity()){$('#simulation-output').innerHTML='<p class="form-error">Revise os valores para simular.</p>';return;}const r=projection(Math.round(Number(f.initial)*100),Math.round(Number(f.monthly)*100),Number(f.rate),Number(f.years));const max=Math.max(...r.points,1);$('#simulation-output').innerHTML=`<div class="simulation-result"><span class="muted" style="font-size:11px">Valor bruto no cenário escolhido</span><h3 class="money">${money(r.total)}</h3><div class="goal-values"><span class="money">Aportes: ${money(r.contributed)}</span><b class="money">Rendimento simulado: ${money(r.total-r.contributed)}</b></div><div class="simulation-bars" aria-label="Evolução anual do cenário">${r.points.map((p,i)=>`<div style="height:${Math.max(2,p/max*100)}%" title="Ano ${i}: ${money(p)}"></div>`).join('')}</div></div>`;animateSimulation();}
function exportCSV(){const rows=[['Descrição','Tipo','Categoria','Data','Valor'],...totals(data,month).list.map(t=>[t.name,t.type==='income'?'Entrada':'Saída',t.category,t.date,(t.type==='income'?1:-1)*t.amount/100])];const cell=v=>typeof v==='number'?String(v).replace('.',','):'"'+String(v).replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const csv='\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`alva-lancamentos-${month}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Planilha exportada.');}
async function handleFiles(fileList){
 const files=[...(fileList||[])];if(!files.length)return;
 let totalAdded=0;const summaries=[],allTxDates=[];
 const combined={transactions:[],debts:[],goals:[],investments:[],profile:{}};
 for(const file of files){
  const parsed=await importDocumentFile(file);
  if(parsed.totalItems>0){
   combined.transactions.push(...parsed.transactions);
   combined.debts.push(...parsed.debts);
   combined.goals.push(...parsed.goals);
   combined.investments.push(...parsed.investments);
   if(parsed.profile?.name)combined.profile.name=parsed.profile.name;
   totalAdded+=parsed.totalItems;
   parsed.transactions.forEach(t=>allTxDates.push(t.date.slice(0,7)));
   summaries.push(file.name);
  }
 }
 if(!totalAdded)throw new Error('Não encontrei lançamentos, dívidas ou metas válidas neste arquivo. Use colunas como Descrição, Valor e Data.');
 let summaryText='';
 await commit(next=>{
  summaryText=applyImportedData(next,combined);
  if(allTxDates.length&&!allTxDates.includes(month))month=allTxDates.sort().at(-1);
 },`Painel atualizado: ${summaryText}!`);
 messages.push({role:'user',content:`📎 Documento anexado: ${summaries.join(', ')}`});
 messages.push({role:'assistant',content:`Li o documento (${summaries.join(', ')}) e atualizei todo o seu painel automaticamente! 🌿\n\nForam reconhecidos e adicionados: ${summaryText}.\nVocê já pode conferir os números atualizados na Visão geral, Lançamentos e Minhas dívidas.`});
 shell();postRender();
}
function postRender(){if(authVisible){authUI.mounted();animateAuth();return;}simulate();syncLayout();animatePage(view);document.querySelectorAll('input[type="number"]').forEach(el=>el.inputMode='decimal');attachEditButtons();const chat=$('#chat-messages');if(chat)chat.scrollTop=chat.scrollHeight;}
function navigate(id){view=id;shell();postRender();window.scrollTo({top:0,behavior:'instant'});}
async function sendMessage(question){if(chatBusy||!question.trim())return;const history=messages.slice(-8);messages.push({role:'user',content:question.trim()});chatBusy=true;view='assistant';shell();postRender();try{const cmd=tryChatCommand(question);if(cmd){await commit(next=>{if(cmd.kind==='debt')next.debts.push(cmd.item);if(cmd.kind==='transaction')next.transactions.push(cmd.item);},'Painel atualizado pela Alva!');messages.push({role:'assistant',content:cmd.reply.replace(/\*\*/g,'')});return;}let answer;if(demo)answer=businessAnswer(question,data,month)||localAnswer(question,data,month);else{try{const result=await api.askAgent(question,history);answer=result.answer;}catch{}if(!answer)answer=businessAnswer(question,data,month)||localAnswer(question,data,month);}messages.push({role:'assistant',content:answer});}catch(err){messages.push({role:'assistant',content:businessAnswer(question,data,month)||localAnswer(question,data,month)});}finally{chatBusy=false;shell();postRender();}}
function authModal(mode='signup'){setMenu(false);authVisible=true;authUI.open(mode);window.scrollTo({top:0,behavior:'instant'});}
async function enterAccount(){const account=await api.loadAccount();data=account.data;ensureBusiness(data,false);authVisible=false;authUI.stop();revision=account.revision;demo=false;messages=[{role:'assistant',content:`Olá, ${data.profile.name.split(' ')[0]||'bem-vindo'}! 🌿 Posso analisar os dados da sua conta, registrar movimentações por conversa ou importar sua planilha (.xlsx, .csv, .ofx) para atualizar seu painel automaticamente.`}];$('#modal').close();navigate('dashboard');toast('Sua conta está pronta. Bem-vindo à Alva!');}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,a,[data-edit]');if(!b)return;try{if(await authUI.click(b))return;if(authVisible)return;if(await businessUI.click(b))return;if(b.dataset.nav){ev.preventDefault();navigate(b.dataset.nav);return;}if(b.dataset.chart){chartMode=b.dataset.chart;shell();postRender();return;}if(b.dataset.question){await sendMessage(b.dataset.question);return;}if(b.dataset.contribute){recordModal('contribute',b.dataset.contribute);return;}if(b.dataset.pay){recordModal('pay',b.dataset.pay);return;}if(b.dataset.edit){recordModal('transaction',b.dataset.edit);return;}if(b.dataset.delete){const t=data.transactions.find(t=>t.id===b.dataset.delete);modal('Excluir lançamento?',`<input type="hidden" name="id" value="${e(t.id)}"><p class="muted" style="font-size:12px;line-height:1.9">${e(t.name)} · ${money(t.amount)}<br>O saldo será recalculado após a exclusão.</p>`,'delete-form','Excluir lançamento');return;}if(b.dataset.deleteDebt){const d=data.debts.find(d=>d.id===b.dataset.deleteDebt);if(!d)return;modal('Excluir dívida?',`<input type="hidden" name="id" value="${e(d.id)}"><p class="muted" style="font-size:12px;line-height:1.9">${e(d.name)} · ${money(d.balance)} em aberto<br>A dívida será removida da sua lista.</p>`,'delete-debt-form','Excluir dívida');return;}const a=b.dataset.action;if(['transaction','goal','debt','investment'].includes(a))recordModal(a);if(a==='import-file')$('#file-importer')?.click();if(a==='close-modal')$('#modal').close();if(a==='export')exportCSV();if(a==='privacy'){hidden=!hidden;shell();postRender();}if(a==='menu')setMenu(true);if(a==='close-menu')setMenu(false);if(a==='prev-month'||a==='next-month'){const d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()+(a==='prev-month'?-1:1));month=dateISO(d).slice(0,7);shell();postRender();}if(a==='login')authModal();if(a==='logout'){await api.logout();clearAccount();authUI.open('login');toast('Você saiu da sua conta.');}if(a==='help')modal('Um passo de cada vez',`<div class="connection-guide"><b>1. Organize seu ponto de partida</b><br>Em Configurações, informe seu saldo inicial e orçamento, ou clique em Importar planilha.<br><br><b>2. Migre sua planilha automaticamente</b><br>Anexe arquivos .xlsx, .csv ou .ofx na Assistente Alva ou no topo do painel para preencher seus lançamentos, dívidas e metas.<br><br><b>3. Dê um destino ao seu dinheiro</b><br>Crie objetivos e acompanhe as parcelas das dívidas.<br><br><b>4. Converse com a Alva</b><br>Pergunte sobre seus gastos ou registre dizendo, por exemplo, "Gastei 60 no mercado".</div>`,'');if(a==='notifications'){const due=data.debts.filter(d=>d.balance>0).sort((a,b)=>a.due.localeCompare(b.due));modal('No seu radar',due.map(d=>`<div class="next-bill"><span class="category-icon">${icon('calendar')}</span><div class="bill-info">${e(d.name)}<p>Vencimento: ${new Date(d.due+'T12:00:00').toLocaleDateString('pt-BR')}</p></div><span class="amount money">${money(d.balance)}</span></div>`).join('')||'<p class="empty">Nenhuma dívida em aberto. 🌱</p>','');}}catch(err){formError(err);}});
document.addEventListener('click',ev=>{if(ev.target.classList.contains('mobile-overlay'))setMenu(false);});
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.dataset.edit)recordModal('transaction',ev.target.dataset.edit);});
document.addEventListener('input',ev=>{if(authVisible){authUI.input(ev.target);return;}if(ev.target.id==='business-search')businessUI.filter();if(ev.target.id==='search')filterTransactions();if(ev.target.closest('#simulator'))simulate();});
document.addEventListener('change',async ev=>{if(ev.target.id==='file-importer'){try{await handleFiles(ev.target.files);}catch(err){formError(err);}finally{ev.target.value='';}return;}if(ev.target.id==='business-type-filter')businessUI.filter();if(['type-filter','category-filter'].includes(ev.target.id))filterTransactions();});
document.addEventListener('dragover',ev=>{if(!authVisible&&ev.dataTransfer?.types?.includes('Files'))ev.preventDefault();});
document.addEventListener('drop',async ev=>{if(authVisible||!ev.dataTransfer?.files?.length)return;ev.preventDefault();try{await handleFiles(ev.dataTransfer.files);}catch(err){formError(err);}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,formId=form.getAttribute('id'),btn=form.querySelector('button[type="submit"]')||form.querySelector('.button');if(btn)btn.disabled=true;try{if(await authUI.submit(form))return;if(authVisible)return;if(await businessUI.submit(form))return;if(formId==='record-form')await submitRecord(form);if(formId==='delete-form'){const id=new FormData(form).get('id');await commit(next=>{next.transactions=next.transactions.filter(t=>t.id!==id||t.linked);},'Lançamento excluído.');}if(formId==='delete-debt-form'){const id=new FormData(form).get('id');await commit(next=>{next.debts=next.debts.filter(d=>d.id!==id);next.transactions.forEach(t=>{if(t.linked===id)delete t.linked;});},'Dívida excluída.');}if(formId==='profile-form'){const f=Object.fromEntries(new FormData(form));await commit(next=>{next.profile={name:f.name.trim(),monthly_budget:Math.round(Number(f.budget)*100),opening_balance:Math.round(Number(f.opening)*100)};},'Perfil atualizado.');}if(formId==='chat-form'){const message=new FormData(form).get('message');await sendMessage(message);}}catch(err){formError(err,form);}finally{if(btn)btn.disabled=false;}});
shell();postRender();
(async()=>{if(api.configured()){try{if(api.session||location.hash.includes('access_token'))authUI.setLoading(true);await api.acceptCallback();if(api.session)await enterAccount();else authUI.setLoading(false);}catch(err){if(err.status===401)api.forgetSession();authVisible=true;authUI.fail(err);}}})();

function clearAccount(){data=emptyData();ensureBusiness(data);revision=0;messages=[];view='dashboard';hidden=false;demo=true;authVisible=true;document.body.classList.remove('screen-privacy');document.querySelector('#modal')?.close();}
window.addEventListener('alva:session-expired',()=>{clearAccount();authUI.open('login');toast('Sua sessão terminou. Entre novamente para continuar.');});
